import React, { useState } from 'react';
import { View, Text, ScrollView, TouchableOpacity, StyleSheet, Alert, TextInput } from 'react-native';
import { COLORS, SIZES } from '../../constants';
import SimulationProgress from '../../components/SimulationProgress';
import { useSimulation } from '../../context/SimulationContext';

const sections = [
  { id: 'presentingIllness', title: 'History of Presenting Illness' },
  { id: 'onset', title: 'Onset' },
  { id: 'location', title: 'Location' },
  { id: 'character', title: 'Character' },
  { id: 'radiation', title: 'Radiation' },
  { id: 'severity', title: 'Severity' },
  { id: 'timing', title: 'Timing' },
  { id: 'associatedSymptoms', title: 'Associated Symptoms' },
  { id: 'pastMedicalHistory', title: 'Past Medical History' },
  { id: 'drugHistory', title: 'Drug History' },
  { id: 'allergies', title: 'Allergies' },
  { id: 'familyHistory', title: 'Family History' },
  { id: 'socialHistory', title: 'Social History' }
];

const HistoryScreen = ({ navigation }) => {
  const { selectedCase, historySectionsViewed, setHistorySectionsViewed } = useSimulation();
  const [question, setQuestion] = useState('');
  const [matchedAnswer, setMatchedAnswer] = useState(null);

  const askQuestion = () => {
    if (!question.trim()) {
      Alert.alert('Question', 'Please type a question');
      return;
    }
    const { matchHistoryQuestion } = require('../../utils/matchingUtils');
    const res = matchHistoryQuestion(question, selectedCase);
    if (!res) {
      Alert.alert('Try again', 'Could you ask that another way?');
      return;
    }
    setMatchedAnswer(res);
    // mark section viewed if id corresponds to a known section
    if (res.id) setHistorySectionsViewed(prev => (prev.includes(res.id) ? prev : [...prev, res.id]));
  };

  if (!selectedCase) {
    return null;
  }

  const toggleSection = sectionId => {
    setHistorySectionsViewed(prev =>
      prev.includes(sectionId) ? prev.filter(id => id !== sectionId) : [...prev, sectionId]
    );
  };

  return (
    <ScrollView style={styles.container} contentContainerStyle={styles.content}>
      <SimulationProgress activeStage="history" />
      <Text style={styles.title}>History</Text>
      <Text style={styles.subtitle}>Review the doctor-verified history one section at a time or ask a question.</Text>

      <View style={styles.askBox}>
        <TextInput
          placeholder="Ask about symptoms, onset, drug history..."
          value={question}
          onChangeText={setQuestion}
          style={styles.input}
        />
        <TouchableOpacity onPress={askQuestion} style={styles.askBtn}>
          <Text style={{ color: '#fff' }}>Ask</Text>
        </TouchableOpacity>
      </View>

      {matchedAnswer ? (
        <View style={styles.matchedCard}>
          <Text style={styles.matchedLabel}>Answer</Text>
          <Text style={styles.matchedText}>{matchedAnswer.answer}</Text>
        </View>
      ) : null}

      {sections.map(section => {
        const opened = historySectionsViewed.includes(section.id);
        const value = selectedCase.history[section.id];
        return (
          <View key={section.id} style={styles.card}>
            <TouchableOpacity onPress={() => toggleSection(section.id)} style={styles.sectionHeader}>
              <Text style={styles.sectionTitle}>{section.title}</Text>
              <Text style={styles.sectionAction}>{opened ? 'Hide' : 'Show'}</Text>
            </TouchableOpacity>
            {opened ? <Text style={styles.sectionText}>{value}</Text> : null}
          </View>
        );
      })}

      <TouchableOpacity style={styles.continueButton} onPress={() => navigation.navigate('Examination')}>
        <Text style={styles.continueText}>Continue to Examination</Text>
      </TouchableOpacity>
    </ScrollView>
  );
};

const styles = StyleSheet.create({
  container: { flex: 1, backgroundColor: COLORS.background },
  content: { padding: SIZES.padding, paddingBottom: 30 },
  title: { fontSize: 24, fontWeight: '700', color: COLORS.text, marginBottom: 8 },
  subtitle: { color: COLORS.muted, marginBottom: 18 },
  card: {
    backgroundColor: COLORS.card,
    borderRadius: SIZES.radius,
    padding: SIZES.padding,
    marginBottom: 14,
    shadowColor: '#000',
    shadowOffset: { width: 0, height: 6 },
    shadowOpacity: 0.05,
    shadowRadius: 12,
    elevation: 3
  },
  sectionHeader: { flexDirection: 'row', justifyContent: 'space-between', alignItems: 'center' },
  sectionTitle: { fontSize: 16, fontWeight: '700', color: COLORS.text, flex: 1, marginRight: 12 },
  sectionAction: { color: COLORS.primary, fontWeight: '700' },
  sectionText: { color: COLORS.muted, marginTop: 12, lineHeight: 22 },
  continueButton: {
    backgroundColor: COLORS.primary,
    borderRadius: 18,
    paddingVertical: 16,
    alignItems: 'center',
    marginTop: 10
  },
  continueText: { color: COLORS.white, fontWeight: '700' }
});

export default HistoryScreen;
